#include <Need.hpp> // Assuming this header provides lnrat, cplx1, ddilog
#include <SpecialFunctions.hpp>
#include <cmath>
#include <complex>
#include <constants_mod.hpp>
#include <iostream>

using namespace constants_mod;

std::complex<double> L0(double x, double y) {
  double denom = one - x / y;
  if (std::abs(denom) < 1e-7) {
    return -cone - cplx1(denom * (half + denom / three));
  } else {
    return lnrat(x, y) / cplx1(denom);
  }
}

std::complex<double> L1(double x, double y) {
  double denom = one - x / y;
  if (std::abs(denom) < 1e-7) {
    return -half * cone - cplx1(denom / three * (one + 0.75 * denom));
  } else {
    return (L0(x, y) + cone) / cplx1(denom);
  }
}

std::complex<double> L2(double x, double y) {
  double r = x / y;
  double denom = one - r;
  if (std::abs(denom) < 1e-7) {
    return (cplx1(10.0) + denom * (cplx1(15.0) + cplx1(18.0) * denom)) /
           cplx1(60.0);
  } else {
    return (lnrat(x, y) - cplx1(half * (r - one / r))) /
           std::pow(cplx1(denom), 3);
  }
}

std::complex<double> L0old(double x, double y) {
  double denom = one - x / y;
  return lnrat(x, y) / cplx1(denom);
}

std::complex<double> L1old(double x, double y) {
  double denom = one - x / y;
  return (L0old(x, y) + cone) / cplx1(denom);
}

std::complex<double> Lsm1(double x1, double y1, double x2, double y2) {
  double r1 = x1 / y1;
  double r2 = x2 / y2;
  double omr1 = one - r1;
  double omr2 = one - r2;
  std::complex<double> dilog1, dilog2;

  if (omr1 > one) {
    dilog1 = cplx1(pisqo6 - ddilog(r1)) - lnrat(x1, y1) * cplx1(std::log(omr1));
  } else {
    dilog1 = cplx1(ddilog(omr1));
  }

  if (omr2 > one) {
    dilog2 = cplx1(pisqo6 - ddilog(r2)) - lnrat(x2, y2) * cplx1(std::log(omr2));
  } else {
    dilog2 = cplx1(ddilog(omr2));
  }

  return dilog1 + dilog2 + lnrat(x1, y1) * lnrat(x2, y2) - cplx1(pisqo6);
}

std::complex<double> Ls0(double x1, double y1, double x2, double y2) {
  double r1 = x1 / y1;
  double r2 = x2 / y2;
  return Lsm1(x1, y1, x2, y2) / cplx1(one - r1 - r2);
}

std::complex<double> Ls1(double x1, double y1, double x2, double y2) {
  double r1 = x1 / y1;
  double r2 = x2 / y2;
  return (Ls0(x1, y1, x2, y2) + L0(x1, y1) + L0(x2, y2)) / cplx1(one - r1 - r2);
}

std::complex<double> Ls2(double x1, double y1, double x2, double y2) {
  double r1 = x1 / y1;
  double r2 = x2 / y2;
  return (Ls1(x1, y1, x2, y2) + (L1(x1, y1) + L1(x2, y2)) / 2.0) /
         cplx1(one - r1 - r2);
}

std::complex<double> Ls3(double x1, double y1, double x2, double y2) {
  double r1 = x1 / y1;
  double r2 = x2 / y2;
  return (Ls2(x1, y1, x2, y2) + (L2(x1, y1) + L2(x2, y2)) / 3.0 -
          1.0 / (6.0 * r1) - 1.0 / (6.0 * r2)) /
         cplx1(one - r1 - r2);
}

std::complex<double> Lsm1_2mht(double s, double t, double m1sq, double m2sq) {
  double r1 = m1sq / t;
  double r2 = m2sq / t;
  double omr1 = one - r1;
  double omr2 = one - r2;
  std::complex<double> dilog1, dilog2;

  if (omr1 > one) {
    dilog1 =
        cplx1(pisqo6 - ddilog(r1)) - lnrat(-m1sq, -t) * cplx1(std::log(omr1));
  } else {
    dilog1 = cplx1(ddilog(omr1));
  }

  if (omr2 > one) {
    dilog2 =
        cplx1(pisqo6 - ddilog(r2)) - lnrat(-m2sq, -t) * cplx1(std::log(omr2));
  } else {
    dilog2 = cplx1(ddilog(omr2));
  }

  return -dilog1 - dilog2 +
         half *
             (lnrat(-s, -m1sq) * lnrat(-s, -m2sq) - std::pow(lnrat(-s, -t), 2));
}

std::complex<double> Lsm1_2mh(double s, double t, double m1sq, double m2sq) {
  return Lsm1_2mht(s, t, m1sq, m2sq) +
         (half * (s - m1sq - m2sq) + m1sq * m2sq / t) * i3m(s, m1sq, m2sq);
}

std::complex<double> Lsm1_2me(double s, double t, double m1sq, double m3sq) {
  std::complex<double> Li2[4];
  double arg[4], omarg[4], f2me;
  std::complex<double> wlog[4];

  // htheta(s) lambda function: half + half * sign(1, s)
  auto htheta = [](double val) -> double { return half + half * sign(val); };

  // f2me = (s + t - m1sq - m3sq) / (s * t - m1sq * m3sq)
  f2me = (s + t - m1sq - m3sq) / (s * t - m1sq * m3sq);

  // arg and omarg initialization
  arg[0] = f2me * s;
  arg[1] = f2me * t;
  arg[2] = f2me * m1sq;
  arg[3] = f2me * m3sq;

  for (int j = 0; j < 4; j++) {
    omarg[j] = one - arg[j];

    // wlog(j) = log(abs(arg(j))) + impi * cplx1(htheta(-arg(j)) * sign(1,
    // f2me))
    wlog[j] = std::log(std::abs(arg[j])) +
              impi * cplx1(htheta(-arg[j]) * std::copysign(1.0, f2me));

    if (omarg[j] > one) {
      // Li2(j) = cplx1(pisqo6 - ddilog(arg(j))) - wlog(j) *
      // cplx1(log(omarg(j)))
      Li2[j] =
          cplx1(pisqo6 - ddilog(arg[j])) - wlog[j] * cplx1(std::log(omarg[j]));
    } else {
      // Li2(j) = cplx1(ddilog(omarg(j)))
      Li2[j] = cplx1(ddilog(omarg[j]));
    }
  }

  // Final result: Lsm1_2me = Li2(1) + Li2(2) - Li2(3) - Li2(4)
  return Li2[0] + Li2[1] - Li2[2] - Li2[3];
}

